  if(this.isHost){const neutral=r.flag==='vsc'||r.flag==='yellow'&&this.inYellow(p.progress);if(neutral&&now-p.penaltyAt>6000&&r.players.some(q=>q.id!==id&&old<q.progress&&q.progress<=p.progress&&!q.dnf&&!q.pose?.crash&&(q.pose?.speed||0)>5))this.penalize(p,'SORPASSO IN NEUTRALIZZAZIONE');if(r.flag==='vsc'&&pose.speed>27){p.violation+=dt;if(p.violation>=3&&now-p.penaltyAt>6000){p.violation=0;this.penalize(p,'VSC');}}else p.violation=Math.max(0,p.violation-dt);if(p.progress>=this.track.length*r.options.laps){p.finishTime=this.elapsed()+p.penalties;p.pose.speed=0;r.leaderFinish??=now;this.publish(true);}}
